export const designProfile = {
  // Primary Colors
  colors: {
    // Brand
    primary: '#6366f1',      // Indigo - Main interactive elements
    primaryLight: '#818cf8',
    primaryDark: '#4f46e5',

    // Semantic
    success: '#10b981',
    warning: '#f59e0b',
    error: '#ef4444',
    info: '#3b82f6',

    // Neutrals - Dark theme
    bg: {
      primary: '#111111',    // Main background
      secondary: '#1a1a1a',  // Cards, panels
      tertiary: '#242424',   // Hover states
      elevated: '#2d2d2d'    // Modals, dropdowns
    },

    text: {
      primary: '#ffffff',
      secondary: '#e5e7eb',  // High contrast secondary
      tertiary: '#9ca3af',   // Medium contrast
      muted: '#6b7280',      // Low contrast, helpers
      placeholder: '#4b5563'
    },

    border: {
      strong: '#404040',
      default: '#2d2d2d',
      soft: '#1f2937',
      subtle: 'rgba(255,255,255,0.05)'
    }
  },

  // Typography
  typography: {
    fontFamily: {
      base: 'system-ui, -apple-system, sans-serif',
      mono: 'Menlo, Monaco, "Courier New", monospace'
    },

    scales: {
      xs: {
        size: '0.75rem',      // 12px
        lineHeight: '1rem',
        fontWeight: 500
      },
      sm: {
        size: '0.875rem',     // 14px
        lineHeight: '1.25rem',
        fontWeight: 400
      },
      base: {
        size: '1rem',         // 16px
        lineHeight: '1.5rem',
        fontWeight: 400
      },
      lg: {
        size: '1.125rem',     // 18px
        lineHeight: '1.75rem',
        fontWeight: 500
      },
      xl: {
        size: '1.25rem',      // 20px
        lineHeight: '1.75rem',
        fontWeight: 600
      },
      '2xl': {
        size: '1.5rem',       // 24px
        lineHeight: '2rem',
        fontWeight: 600
      }
    }
  },

  // Spacing System (8px base)
  spacing: {
    xs: '0.25rem',   // 4px
    sm: '0.5rem',    // 8px
    md: '1rem',      // 16px
    lg: '1.5rem',    // 24px
    xl: '2rem',      // 32px
    '2xl': '3rem'    // 48px
  },

  // Border Radius
  radius: {
    xs: '0.25rem',   // 4px - tiny elements
    sm: '0.375rem',  // 6px - buttons, small components
    md: '0.5rem',    // 8px - standard
    lg: '0.75rem',   // 12px - large cards, panels
    xl: '1rem',      // 16px - modals, major sections
    full: '9999px'   // Pills, avatars
  },

  // Shadows
  shadows: {
    none: 'none',
    xs: '0 1px 2px 0 rgba(0,0,0,0.05)',
    sm: '0 1px 3px 0 rgba(0,0,0,0.1)',
    md: '0 4px 6px -1px rgba(0,0,0,0.1)',
    lg: '0 10px 15px -3px rgba(0,0,0,0.2)',
    xl: '0 20px 25px -5px rgba(0,0,0,0.3)',
    modal: '0 20px 25px -5px rgba(0,0,0,0.5)'
  },

  // Transitions
  transitions: {
    fast: 'all 0.15s ease',
    base: 'all 0.2s ease',
    slow: 'all 0.3s ease'
  }
}

export default designProfile
